    if isinstance(opp, (list, tuple)) and len(opp) >= 2:
        ox, oy = opp[0], opp[1]
        dx = clamp(x - ox)
        dy = clamp(y - oy)
        if dx != 0 or dy != 0:
            return [dx, dy]

    # 2) Move toward nearest resource if present
    resources = obs.get('resources', [])
