            rx, ry = r[0], r[1]
            d = abs(rx - x) + abs(ry - y)
            if bestd is None or d < bestd:
                bestd = d
                best = (rx, ry)
        if best is not None:
            rx, ry = best
            dx = clamp(rx - x)
            dy = clamp(ry - y)
            if dx != 0 or dy != 0:
                return [dx, dy]

    # 3) Gentle exploration toward grid center
    w = obs.get('grid_width', 0)
